/**
 * Class to manage the event listeners
 * and dispatch events
 */
export default class Events {
    listeners = new Map();
    /** Assign a listener to an event */
    addEventListener(type, listenerFn, options) {
        const listeners = this.listeners.get(type) || new Set();
        const listener = [listenerFn, options];
        listeners.add(listener);
        this.listeners.set(type, listeners);
        // Remove on abort
        if (options?.signal) {
            options.signal.addEventListener("abort", () => {
                listeners.delete(listener);
            });
        }
        return this;
    }
    /** Dispatch an event */
    async dispatchEvent(event) {
        const { type } = event;
        const listeners = this.listeners.get(type);
        if (listeners) {
            for (const listener of listeners) {
                const [listenerFn, listenerOptions] = listener;
                // Remove the listener if it's a once listener
                if (listenerOptions?.once) {
                    listeners.delete(listener);
                }
                if ((await listenerFn(event)) === false) {
                    return false;
                }
            }
        }
        return true;
    }
}
